<?php
namespace App\Http\Controllers;
use App\Models\User; use Illuminate\Http\Request;
class DriverController extends Controller { public function index(){ $drivers=User::latest()->paginate(15); return view('admin.drivers.index',compact('drivers')); } public function create(){return view('admin.drivers.create');} public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:150','email'=>'required|email|unique:users,email','phone'=>'nullable|string|max:50','role'=>'required|in:driver,admin','password'=>'required|string|min:6|confirmed']); User::create(array_merge($d,['active'=>true])); return redirect()->route('drivers.index')->with('success','بەکارهێنەر بەسەرکەوتوویی زیادکرا.');} public function edit(User $driver){return view('admin.drivers.edit',compact('driver'));} public function update(Request $r,User $driver){$d=$r->validate(['name'=>'required|string|max:150','email'=>'required|email|unique:users,email,'.$driver->id,'phone'=>'nullable|string|max:50','role'=>'required|in:driver,admin','password'=>'nullable|string|min:6|confirmed','active'=>'nullable|boolean']); if(empty($d['password'])) unset($d['password']); $driver->update($d); return redirect()->route('drivers.index')->with('success','زانیاری بەکارهێنەر نوێکرایەوە.');} public function destroy(User $driver){ if($driver->id===auth()->id()) return back()->with('error','ناتوانیت هەژماری خۆت ناچالاک بکەیت.'); if($driver->movements()->where('status','out')->exists()) return back()->with('error','ئەم بەکارهێنەرە گەشتێکی کراوەی هەیە.'); $driver->update(['active'=>false]); return back()->with('success','بەکارهێنەر ناچالاک کرا.'); } }
